    std::vector<int> timeTaken(std::vector<int>& arrival, std::vector<int>& state) {
        int n = arrival.size();
        std::queue<int> enter_q, exit_q;
        std::vector<int> ans(n, 0);
        int cur_time = 0, last_state = -1, idx = 0;

        while (idx < n || !enter_q.empty() || !exit_q.empty()) {
            if (enter_q.empty() && exit_q.empty() && cur_time < arrival[idx]) {
                cur_time = arrival[idx];
                last_state = -1;
            }
            while (idx < n && arrival[idx] <= cur_time) {
                if (state[idx] == 1) exit_q.push(idx);
                else enter_q.push(idx);
                idx++;
            }
            if (last_state == -1 || last_state == 1) {
                if (!exit_q.empty()) {
                    int p = exit_q.front(); exit_q.pop();
                    ans[p] = cur_time;
                    last_state = 1;
                } else if (!enter_q.empty()) {
                    int p = enter_q.front(); enter_q.pop();
                    ans[p] = cur_time;
                    last_state = 0;
                } else last_state = -1;
            } else {
                if (!enter_q.empty()) {
                    int p = enter_q.front(); enter_q.pop();
                    ans[p] = cur_time;
                    last_state = 0;
                } else if (!exit_q.empty()) {
                    int p = exit_q.front(); exit_q.pop();
                    ans[p] = cur_time;
                    last_state = 1;
                } else last_state = -1;
            }
            cur_time++;
        }
        return ans;
    }
