    public int[] timeTaken(int[] arrival, int[] state) {
        int n = arrival.length;
        java.util.Queue<Integer> enterQ = new java.util.LinkedList<>();
        java.util.Queue<Integer> exitQ = new java.util.LinkedList<>();
        int[] ans = new int[n];
        int curTime = 0, lastState = -1, idx = 0;

        while (idx < n || !enterQ.isEmpty() || !exitQ.isEmpty()) {
            if (enterQ.isEmpty() && exitQ.isEmpty() && curTime < arrival[idx]) {
                curTime = arrival[idx];
                lastState = -1;
            }
            while (idx < n && arrival[idx] <= curTime) {
                if (state[idx] == 1) exitQ.offer(idx);
                else enterQ.offer(idx);
                idx++;
            }
            if (lastState == -1 || lastState == 1) {
                if (!exitQ.isEmpty()) {
                    int p = exitQ.poll();
                    ans[p] = curTime;
                    lastState = 1;
                } else if (!enterQ.isEmpty()) {
                    int p = enterQ.poll();
                    ans[p] = curTime;
                    lastState = 0;
                } else lastState = -1;
